css:
@font-face {
  font-family: 'Certificate';
  src: url("/assets/one_lms/css/forte.ttf");
  font-weight: bold;
}

@font-face {
  font-family: 'heading';
  src: url("/assets/one_lms/css/Castellar_Regular.ttf");
  font-weight: normal;
}

.certificate-format {
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 100vh;
}

.certificate-logo-image{
    margin-left: -130px;margin-top: -5px;
}

.certificate-top-text {
            font-family: 'Calibri', sans-serif;
            font-size: 0.88125rem;
            white-space: nowrap; /* Ensures the text stays in one line */
            display: inline-flex;
            align-items: center;
            justify-content: flex-end;
            margin-top: 35px;
            margin-right: 40px;
        }

.text-right {
            display: flex;
            align-items: center;
            justify-content: flex-end;
            flex-wrap: nowrap; /* Prevent wrapping */
        }

.certificate-body2{
    margin-top: 3.5rem;
}

.certificate-heading1{
    font-family: 'heading';
    font-size: 1.75rem;
}

.certificate-heading2{
    font-family: 'heading';
    font-size: 1rem;
}

.certificate-text {
	font-family: 'Certificate';
	font-size: 3rem;
}

.certificate-text2{
	font-size: 1.125rem;
	font-family: 'Calibri', sans-serif;
}

.bottom-certificate-text{
    font-family: 'Certificate';
	font-size: 1rem;
}

.bottom-certificate-text2{
	font-size: 1rem;
	color:grey;
	font-family: 'Calibri', sans-serif;
}

.bottom-certificate-divider {
    margin: 0.5rem 5rem;
    border-top: 1px solid;
    width: 11rem
}

.inner-border {
    background: url(/assets/one_lms/images/IKAS-background.png);
    background-repeat: no-repeat;
    background-size: cover;
    background-position: center center;

    /* Landscape size */
   width: 3000px;
   height: 100vh; /* Full viewport height */
    /*height: 389px;*/

    /* Ensure it adapts */
    max-width: 100%;
    max-height: 100%;
    border-radius: 8px;
    text-align: center;
    padding: 0;
}



.certificate-footer {
    margin: 4rem auto 2.9375rem;
    width: 100%;
    padding: 0;
}

.top-certificate-divider {
    margin: 0.5rem 10rem;
    border-top: 1px solid;
}


.training-details{
    font-size: 1.2rem;
}

#certificate_format .row:not(.section-break) {
    margin-top: 0px !important;
}
/**/

 /* Apply the translate and rotate transformation 
           for our text to look curved  */ 
.C1 {
    transform: translate(25px, -6px) rotate(-17deg);
}

.e1 {
    transform: translate(20px, -12px) rotate(-17deg);
}

.r {
    transform: translate(18px, -18px) rotate(-14deg);
}

.t1 {
    transform: translate(15px, -23px) rotate(-13deg);
}

.i1 {
